  Eq.{1}
    (List.length.{0}
      (Allow.FreshTier1.arguments required Allow.FreshTier1.Operation.advisory Allow.FreshTier1.Variant.tier1))
    (HAdd.hAdd.{0, 0, 0}
      (List.length.{0}
        (Allow.FreshTier1.arguments required Allow.FreshTier1.Operation.advisory Allow.FreshTier1.Variant.baseline))
      1)

@Allow.FreshTier1.running_requires_both_identity_checks : ∀ {identity durable : Nat} {s : Allow.FreshTier1.Worker},
  Allow.FreshTier1.Reachable identity durable s →
    Eq.{1} s.phase Allow.FreshTier1.Phase.running → Eq.{1} s.buildChecked true ∧ Eq.{1} s.solverChecked true

@Allow.FreshTier1.selection_requires_complete_comparison : ∀ {same contained : Bool}
  {runs : List.{0} Allow.FreshTier1.Run},
  Allow.FreshTier1.SelectTier1 same contained runs → Eq.{1} same true ∧ Eq.{1} contained true

@Allow.FreshTier1.selection_requires_every_run_target : ∀ {same contained : Bool} {runs : List.{0} Allow.FreshTier1.Run}
  {run : Allow.FreshTier1.Run},
  Allow.FreshTier1.SelectTier1 same contained runs →
    Membership.mem.{0, 0} runs run → Eq.{1} run.failures 0 ∧ LT.lt.{0} run.p95Micros 300000

@Allow.FreshTier1.failed_or_slow_run_blocks_selection : ∀ {same contained : Bool} {runs : List.{0} Allow.FreshTier1.Run}
  {run : Allow.FreshTier1.Run},
  Membership.mem.{0, 0} runs run →
    Ne.{1} run.failures 0 ∨ LE.le.{0} 300000 run.p95Micros → ¬Allow.FreshTier1.SelectTier1 same contained runs
